<script setup lang="ts">import{nim,shortWallet,policyCopy}from'~/utils/presentation';const p=defineProps<{event:any;wallet?:string}>();const policy=computed(()=>policyCopy(p.event?.payment_mode));defineEmits(['confirm','close'])</script>
<template><div class="dialog-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-label="Confirm payment"><EventPolicyBadge :mode="event.payment_mode"/><h2>{{ event.title }}</h2><MoneyAmount :luna="event.amount_luna"/><p>{{ policy.summary }}</p><div class="meta"><div class="meta-row"><span>Wallet</span><strong class="mono">{{ shortWallet(wallet) }}</strong></div><div class="meta-row"><span>Cancellation</span><strong>{{ event.participant_cancellation_policy==='NON_REFUNDABLE' ? 'Nonrefundable' : 'Refund before cutoff' }}</strong></div></div><StatusNotice v-if="event.payment_mode==='REFUNDABLE_DEPOSIT'" tone="waiting" title="Custodial deposit" message="ShowUp holds this deposit until check-in, cancellation, or the no-show decision is settled."/><button @click="$emit('confirm')">{{ policy.cta }} for {{ nim(event.amount_luna) }}</button><button class="secondary" @click="$emit('close')">Review event</button></section></div></template>
